WHERE resource_type = #{resourceType}
  AND resource_id = #{resourceId}
  AND target_type = #{targetType}
  AND (
    (#{targetType} = 'USER' AND target_user = #{targetUser})
    OR (#{targetType} = 'ROLE' AND target_role = #{targetRole})
  )

